-- ==============================================================================
-- 2DQH 연구실 시약 및 소모품 위치 안내 시드 데이터 (337종)
-- ==============================================================================

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  location = EXCLUDED.location,
  sub_location = EXCLUDED.sub_location,
  specification = EXCLUDED.specification;